<script setup lang="ts">
const route = useRoute(); const password = ref(''); const confirm = ref(''); const message = ref(''); const error = ref(''); const busy = ref(false)
async function reset() { error.value = ''; if (password.value !== confirm.value) { error.value = 'Passwords do not match.'; return }; busy.value = true; try { message.value = (await $fetch<any>('/api/auth/reset-password', { method: 'POST', body: { token: route.query.token, password: password.value } })).message } catch (e: any) { error.value = e.data?.statusMessage || 'Unable to reset password.' } finally { busy.value = false } }
</script>
<template><main class="page auth-page"><section class="auth-shell" style="padding:5rem 1.5rem"><div class="auth-panel"><div class="auth-panel__inner"><h1>Set a new password</h1><form class="auth-form" @submit.prevent="reset"><div class="auth-field"><label>New password</label><input v-model="password" type="password" minlength="12" placeholder="12+ chars, letters and numbers" required></div><div class="auth-field"><label>Confirm password</label><input v-model="confirm" type="password" minlength="12" required></div><p v-if="error" style="color:#b42318">{{ error }}</p><p v-if="message" style="color:#087443">{{ message }}</p><AppButton type="submit" :disabled="busy">{{ busy ? 'Saving…' : 'Save password' }}</AppButton></form><NuxtLink v-if="message" to="/loginscreen">Log in</NuxtLink></div></div></section></main></template>
